// What the parts of the parser share: the words that can not be names, and finding files regardless of case.
#pragma once
#include <algorithm>
#include <filesystem>
#include <set>
#include <string>

#include "util.hpp"

namespace blitz::parser_detail {
	inline std::string lower(std::string text)
	{
		std::transform(text.cbegin(), text.cend(), text.begin(), blitz::utility::utf8_safe_tolower);
		return text;
	}

	// Words that can never be used as a variable or function name.
	inline const std::set<std::string> reserved = {
		"then",  "to",     "step",   "else",    "elseif", "endif",     "end",    "wend",  "next", "until", "forever", "case",
		"default", "local", "global", "const",   "if",     "while",     "repeat", "for",   "select", "function", "endfunction", "endselect",
		"return", "exit",  "include", "dim",    "type",   "and",       "or",     "xor",   "mod",  "shl",   "shr",     "sar",
		"not",    "data",   "read",   "restore", "goto",   "gosub",  "dim",    "type",   "endtype", "field", "new",  "delete", "insert", "before", "after", "each", "first", "last",
	};

	// Finds a file whose name differs from the given one only by case, which is how paths are written in Blitz programs.
	inline std::filesystem::path find_file(std::filesystem::path const& wanted)
	{
		std::error_code ec;
		if (std::filesystem::exists(wanted, ec)) {
			return wanted;
		}
		std::filesystem::path current = wanted.is_absolute() ? wanted.root_path() : std::filesystem::path();
		for (auto const& part : wanted.relative_path()) {
			std::filesystem::path next = current / part;
			if (!std::filesystem::exists(next, ec)) {
				bool found = false;
				for (auto const& entry : std::filesystem::directory_iterator(current.empty() ? std::filesystem::path(".") : current, ec)) {
					if (lower(entry.path().filename().string()) == lower(part.string())) {
						next  = current / entry.path().filename();
						found = true;
						break;
					}
				}
				if (!found) {
					return wanted;
				}
			}
			current = next;
		}
		return current;
	}

	// Things that exist in Blitz, but that we do not (yet) know how to compile.
	inline const std::set<std::string> unsupported = {
		
	};
} // namespace blitz::parser_detail
